package com.deathscoffer;

import lombok.Value;

@Value
class CofferItem
{
	String name;
	int itemId;
	int gePrice;
	int haPrice;
	int quantity;

	int getCofferValue()
	{
		return (int) (gePrice * 1.05);
	}

	int getProfitOverHa()
	{
		return getCofferValue() - haPrice;
	}
}

package com.deathscoffer;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.bank.BankSearch;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(
	name = "Death's Coffer Advisor",
	description = "Finds bank items more profitable to add to Death's Coffer (105% GE value) than to sell on the GE or High Alch",
	tags = {"bank", "death", "coffer", "alchemy", "price", "profit", "gp"}
)
@PluginDependency(BankTagsPlugin.class)
public class DeathsCofferPlugin extends Plugin
{
	// Death's Coffer requires items to be worth at least 10,000 gp on the GE
	private static final int MIN_GE_PRICE = 10_000;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private DeathsCofferConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private BankSearch bankSearch;

	@Inject
	private BankTagsService bankTagsService;

	@Inject
	private Gson gson;

	private static final String KEY_LAST_SCAN_RESULTS = "lastScanResults";
	private static final String KEY_LAST_SCAN_TIMESTAMP = "lastScanTimestamp";
	private static final Type COFFER_ITEM_LIST_TYPE = new TypeToken<List<CofferItem>>(){}.getType();

	private DeathsCofferPanel panel;
	private NavigationButton navButton;
	private List<CofferItem> lastResults = Collections.emptyList();
	// Epoch millis of the scan that produced lastResults (0 if never scanned this run
	// and no persisted snapshot loaded). Preserved across exclusion edits.
	private long lastScanTimestamp = 0L;
	private final Set<Integer> filterItemIds = new HashSet<>();
	private boolean filterActive = false;
	// Set when the user clicks a bank-tag tab; cleared when they switch to a regular bank tab
	// or close the bank. Used so we can skip applying our visual filter while a tag tab is
	// open — bank-tag layouts hide+reshow items and our filter would cause the layout to
	// render greyed placeholders for items we hide.
	private boolean tagTabKnownActive = false;
	// Gates auto-scan-on-first-bank-open to one fire per login session.
	private boolean scannedThisSession = false;
	// id -> resolved display name, populated on the client thread, read by the panel
	private volatile Map<Integer, String> resolvedExclusions = Collections.emptyMap();

	@Provides
	DeathsCofferConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DeathsCofferConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		panel = new DeathsCofferPanel(this, config);
		navButton = NavigationButton.builder()
			.tooltip("Death's Coffer Advisor")
			.icon(buildNavIcon())
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		refreshExclusionsCache();
		// If the plugin is enabled mid-session we won't see a LOGGED_IN GameStateChanged,
		// so try to load the persisted snapshot for the current profile right away.
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				loadPersistedScan();
			}
		});
	}

	@Override
	protected void shutDown() throws Exception
	{
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
		lastResults = Collections.emptyList();
		lastScanTimestamp = 0L;
		scannedThisSession = false;
	}

	@SuppressWarnings("unused")
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!DeathsCofferConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if ("excludedItems".equals(event.getKey()))
		{
			// Resolve names on client thread, then push to panel
			refreshExclusionsCache();
		}
		else
		{
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.onConfigChanged();
				}
			});
		}
	}

	private void refreshExclusionsCache()
	{
		clientThread.invokeLater(() ->
		{
			Set<Integer> ids = parseExclusionIds(config.excludedItems());
			Map<Integer, String> resolved = new LinkedHashMap<>();
			for (Integer id : ids)
			{
				String name;
				try
				{
					ItemComposition comp = itemManager.getItemComposition(id);
					name = comp != null && comp.getName() != null && !comp.getName().isEmpty()
						? comp.getName()
						: "Item #" + id;
				}
				catch (Exception ex)
				{
					name = "Item #" + id;
				}
				resolved.put(id, name);
			}
			resolvedExclusions = Collections.unmodifiableMap(resolved);
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.onConfigChanged();
				}
			});
		});
	}

	@SuppressWarnings("unused")
	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			// Bank closed — reset our state so a fresh bank-open starts clean.
			tagTabKnownActive = false;
			if (filterActive)
			{
				clearFilterStateNoLayout();
			}
		}
	}

	@SuppressWarnings("unused")
	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() != InterfaceID.BANKMAIN)
		{
			return;
		}
		if (!config.autoScanOnFirstOpen() || scannedThisSession)
		{
			return;
		}
		// Mark optimistically so we don't fire twice if the widget re-loads while
		// the deferred scan is still waiting for the container to populate.
		scannedThisSession = true;
		// Retry until the bank container is populated (BooleanSupplier overload —
		// return false to be re-invoked next client tick). WidgetLoaded usually
		// fires before BANK is filled.
		clientThread.invokeLater(() ->
		{
			if (client.getItemContainer(InventoryID.BANK) == null)
			{
				return false;
			}
			// Auto-scan populates the side panel only; the in-bank visual filter is
			// reserved for manual scans so the bank view isn't unexpectedly hidden
			// the moment the user opens it.
			doScan(false);
			return true;
		});
	}

	@SuppressWarnings("unused")
	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.LOGGING_IN)
		{
			scannedThisSession = false;
		}
		else if (state == GameState.LOGGED_IN)
		{
			loadPersistedScan();
		}
	}

	@SuppressWarnings("unused")
	@Subscribe(priority = -100) // run after bank tags so we don't override its decisions
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		if (!filterActive)
		{
			return;
		}
		if (!"bankSearchFilter".equals(event.getEventName()))
		{
			return;
		}
		int[] intStack = client.getIntStack();
		int intStackSize = client.getIntStackSize();
		int itemId = intStack[intStackSize - 1];
		if (itemId == -1)
		{
			return;
		}
		// Restrictive filter: only ever HIDE (write 0). Never write 1, so we never
		// undo a hide decision from another plugin. The bank script's default value
		// is 1 (show), so items we want shown stay visible unless someone else hides
		// them. Result: visible iff every active filter agrees.
		if (!filterItemIds.contains(itemId))
		{
			intStack[intStackSize - 2] = 0;
		}
	}

	@SuppressWarnings("unused")
	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarbitId() != VarbitID.BANK_CURRENTTAB)
		{
			return;
		}
		// Tab 0 is the "all items" view we want when our filter is active — and we set
		// it ourselves in doScan to widen the bank's scope. Switching to a non-zero tab,
		// on the other hand, narrows the bank to a single tab's items and is a clear
		// "user is navigating" signal — drop our filter.
		if (event.getValue() != 0)
		{
			tagTabKnownActive = false;
			if (filterActive)
			{
				clearFilterStateNoLayout();
			}
		}
	}

	@SuppressWarnings("unused")
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		String option = event.getMenuOption();
		if (option == null)
		{
			return;
		}
		// Bank Tags exposes tag-tab clicks with this menu option (TabInterface.VIEW_TAB).
		// Treat the click as: "user has opened a tag tab" — flag the state and drop our
		// filter so the tag's layout can render cleanly.
		if ("View tag tab".equals(option) || "View tag tabs".equals(option))
		{
			tagTabKnownActive = true;
			if (filterActive)
			{
				clearFilterStateNoLayout();
			}
		}
	}

	/**
	 * Drop the filter state but don't trigger a layout — used when the user's own action
	 * (tab switch, tag tab click) is about to re-lay the bank anyway. Avoids a redundant
	 * layoutBank() that would fight the action in progress.
	 */
	private void clearFilterStateNoLayout()
	{
		filterActive = false;
		filterItemIds.clear();
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.onFilterStateChanged();
			}
		});
	}

	void scanBank()
	{
		clientThread.invokeLater(() -> doScan(true));
	}

	private void doScan(boolean applyFilter)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.showError("Not logged in.");
				}
			});
			return;
		}

		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (bank == null)
		{
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.showError("Bank is not open. Open your bank first.");
				}
			});
			return;
		}

		Set<Integer> excludedIds = parseExclusionIds(config.excludedItems());
		List<CofferItem> results = new ArrayList<>();
		Set<Integer> matchedBankIds = new HashSet<>();

		for (Item item : bank.getItems())
		{
			int itemId = item.getId();
			int quantity = item.getQuantity();

			if (itemId <= 0 || quantity <= 0)
			{
				continue;
			}

			// Check placeholder against the *raw* bank item id — canonicalize() strips
			// placeholder state, so we'd miss it otherwise.
			ItemComposition rawComp = itemManager.getItemComposition(itemId);
			if (rawComp.getPlaceholderTemplateId() != -1)
			{
				continue;
			}

			// Resolve noted items to their base item before price lookups
			int canonicalId = itemManager.canonicalize(itemId);

			if (excludedIds.contains(canonicalId))
			{
				continue;
			}

			int gePrice = (int) Math.min(itemManager.getItemPrice(canonicalId), Integer.MAX_VALUE);

			if (gePrice < MIN_GE_PRICE)
			{
				continue;
			}

			ItemComposition comp = canonicalId == itemId ? rawComp : itemManager.getItemComposition(canonicalId);

			int haPrice = comp.getHaPrice();

			if (haPrice <= 0)
			{
				continue;
			}

			String name = comp.getName();

			// Death's Coffer pays 105% of GE price.
			// Profitable when: GE price < HA price  (so HA beats plain GE sale)
			//              AND GE price * 1.05 > HA price  (but Coffer beats HA)
			double cofferValue = gePrice * 1.05;
			if (gePrice < haPrice && cofferValue > haPrice)
			{
				results.add(new CofferItem(name, canonicalId, gePrice, haPrice, quantity));
				// Use the actual bank slot id (may be noted) so the in-bank filter matches what's rendered
				matchedBankIds.add(itemId);
			}
		}

		lastResults = results;
		lastScanTimestamp = System.currentTimeMillis();
		persistLastScan();

		boolean canApplyFilter = applyFilter && config.filterBankView() && !results.isEmpty();

		if (canApplyFilter)
		{
			// If a bank tag tab is open, close it first. The tag-tab layout system
			// positions items in fixed slots and would render hidden items as greyed
			// placeholders — closeBankTag drops the tag layout so our search filter
			// gets a clean grid. Using the published BankTagsService interface here
			// is the only way to programmatically exit a tag tab; there is no
			// equivalent varbit or script we can fire ourselves.
			if (bankTagsService.getActiveTag() != null)
			{
				bankTagsService.closeBankTag();
				tagTabKnownActive = false;
			}

			filterItemIds.clear();
			filterItemIds.addAll(matchedBankIds);
			filterActive = true;
			// Force the bank onto the main "all items" tab. A tab-restricted view would
			// narrow our filter to (current tab ∩ scan results), so an item flagged by the
			// scan but stored in a different tab would be hidden by tab assignment before
			// our filter ever sees it. The onVarbitChanged listener ignores 0-valued changes
			// so this assignment doesn't ricochet back and clear the filter we're about to apply.
			if (client.getVarbitValue(VarbitID.BANK_CURRENTTAB) != 0)
			{
				client.setVarbit(VarbitID.BANK_CURRENTTAB, 0);
			}
			bankSearch.layoutBank();
		}
		else if (applyFilter && filterActive)
		{
			// Manual re-scan returned nothing or filter is disabled in config.
			// Drop any existing filter so the bank view is consistent with the new state.
			// Auto-scan deliberately leaves the existing filter alone — it never touches
			// the bank view.
			filterActive = false;
			filterItemIds.clear();
			bankSearch.layoutBank();
		}

		final long ts = lastScanTimestamp;
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.displayResults(results, ts);
				panel.onFilterStateChanged();
			}
		});
	}

	boolean isFilterActive()
	{
		return filterActive;
	}

	void clearFilter()
	{
		clientThread.invokeLater(() ->
		{
			if (!filterActive)
			{
				return;
			}
			filterActive = false;
			filterItemIds.clear();
			bankSearch.layoutBank();
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.onFilterStateChanged();
				}
			});
		});
	}

	List<CofferItem> getLastResults()
	{
		return lastResults;
	}

	// Cached (id -> resolved name) map. The panel reads this directly.
	Map<Integer, String> getExcludedItems()
	{
		return resolvedExclusions;
	}

	void addExclusion(int itemId)
	{
		if (itemId <= 0)
		{
			return;
		}
		Set<Integer> current = new java.util.LinkedHashSet<>(parseExclusionIds(config.excludedItems()));
		if (!current.add(itemId))
		{
			return;
		}
		config.setExcludedItems(formatIdCsv(current));
		// Refresh on the client thread — itemManager.canonicalize() and bankSearch.layoutBank()
		// must run there.
		clientThread.invokeLater(() -> applyExclusionToCurrentResults(itemId));
	}

	/**
	 * Drop the just-excluded item from in-memory scan results and the bank-view filter,
	 * then push fresh state to the bank UI and side panel so the user sees the change
	 * without having to re-run the scan. Must be called on the client thread.
	 */
	private void applyExclusionToCurrentResults(int excludedCanonicalId)
	{
		if (!lastResults.isEmpty())
		{
			lastResults = lastResults.stream()
				.filter(it -> it.getItemId() != excludedCanonicalId)
				.collect(Collectors.toList());
		}

		boolean filterChanged = false;
		if (filterActive)
		{
			Set<Integer> keep = new HashSet<>();
			for (Integer id : filterItemIds)
			{
				if (itemManager.canonicalize(id) != excludedCanonicalId)
				{
					keep.add(id);
				}
			}
			if (keep.size() != filterItemIds.size())
			{
				filterItemIds.clear();
				filterItemIds.addAll(keep);
				filterChanged = true;
			}
			if (filterItemIds.isEmpty())
			{
				filterActive = false;
			}
		}

		if (filterChanged)
		{
			bankSearch.layoutBank();
		}

		// Re-persist so the stored snapshot stays in sync with the in-memory results.
		// Timestamp is preserved — exclusion is not a new scan.
		persistLastScan();

		final List<CofferItem> snapshot = lastResults;
		final long ts = lastScanTimestamp;
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.displayResults(snapshot, ts);
				panel.onFilterStateChanged();
			}
		});
	}

	void removeExclusion(int itemId)
	{
		Set<Integer> current = new java.util.LinkedHashSet<>(parseExclusionIds(config.excludedItems()));
		if (!current.remove(itemId))
		{
			return;
		}
		config.setExcludedItems(formatIdCsv(current));
	}

	/**
	 * Write the current scan snapshot to per-character config. Scoped via
	 * RSProfileConfiguration so each character keeps its own history.
	 */
	private void persistLastScan()
	{
		try
		{
			String json = gson.toJson(lastResults, COFFER_ITEM_LIST_TYPE);
			configManager.setRSProfileConfiguration(DeathsCofferConfig.GROUP, KEY_LAST_SCAN_RESULTS, json);
			configManager.setRSProfileConfiguration(DeathsCofferConfig.GROUP, KEY_LAST_SCAN_TIMESTAMP, lastScanTimestamp);
		}
		catch (Exception ex)
		{
			log.warn("Failed to persist last scan", ex);
		}
	}

	/**
	 * Load the persisted snapshot for the active character (if any) and push it to the
	 * panel. Called on LOGGED_IN and on startUp if the user enables the plugin while
	 * already logged in. Must be called from the client thread (RSProfile lookups read
	 * client state).
	 */
	private void loadPersistedScan()
	{
		String json = configManager.getRSProfileConfiguration(DeathsCofferConfig.GROUP, KEY_LAST_SCAN_RESULTS);
		if (json == null || json.isEmpty())
		{
			return;
		}
		List<CofferItem> stored;
		try
		{
			stored = gson.fromJson(json, COFFER_ITEM_LIST_TYPE);
		}
		catch (JsonSyntaxException ex)
		{
			log.warn("Discarding malformed persisted scan", ex);
			return;
		}
		if (stored == null)
		{
			return;
		}
		Long ts = configManager.getRSProfileConfiguration(DeathsCofferConfig.GROUP, KEY_LAST_SCAN_TIMESTAMP, Long.class);
		lastResults = stored;
		lastScanTimestamp = ts != null ? ts : 0L;
		final List<CofferItem> snapshot = lastResults;
		final long tsFinal = lastScanTimestamp;
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.displayResults(snapshot, tsFinal);
			}
		});
	}

	private static Set<Integer> parseExclusionIds(String csv)
	{
		if (csv == null || csv.isBlank())
		{
			return Collections.emptySet();
		}
		Set<Integer> ids = new java.util.LinkedHashSet<>();
		for (String token : csv.split(","))
		{
			String trimmed = token.trim();
			if (trimmed.isEmpty())
			{
				continue;
			}
			try
			{
				ids.add(Integer.parseInt(trimmed));
			}
			catch (NumberFormatException ignored)
			{
				// Skip non-numeric tokens silently — they're either stale name-based entries
				// from an older config or a typo the user can correct in the config screen
			}
		}
		return ids;
	}

	private static String formatIdCsv(Set<Integer> ids)
	{
		return ids.stream().map(String::valueOf).collect(Collectors.joining(", "));
	}

	private static BufferedImage buildNavIcon()
	{
		int size = 17;
		BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		g.setColor(new Color(200, 150, 20));
		g.fillOval(1, 1, size - 2, size - 2);

		g.setColor(new Color(140, 100, 10));
		g.drawOval(1, 1, size - 2, size - 2);

		g.setColor(Color.BLACK);
		g.setFont(new Font("SansSerif", Font.BOLD, 10));
		g.drawString("D", 5, 12);

		g.dispose();
		return img;
	}
}

package com.deathscoffer;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.text.NumberFormat;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTabbedPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

class DeathsCofferPanel extends PluginPanel
{
	private static final Color PROFIT_GREEN = new Color(0, 200, 83);
	private static final DateTimeFormatter TIMESTAMP_FMT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");

	private final DeathsCofferPlugin plugin;
	private final DeathsCofferConfig config;

	// Scan tab pieces
	private final JPanel resultsContainer = new JPanel();
	private JLabel statusLabel;
	private JLabel totalCofferLabel;
	private JLabel totalProfitLabel;
	private JLabel lastScanLabel;
	private JButton showAllButton;

	// Exclusions tab pieces
	private final JPanel exclusionsContainer = new JPanel();
	private JLabel exclusionsHeaderLabel;

	private List<CofferItem> currentItems = Collections.emptyList();

	DeathsCofferPanel(DeathsCofferPlugin plugin, DeathsCofferConfig config)
	{
