		setBackground(ColorScheme.DARK_GRAY_COLOR);

		add(buildTitleBar(), BorderLayout.NORTH);

		JTabbedPane tabs = new JTabbedPane();
		tabs.setBackground(ColorScheme.DARK_GRAY_COLOR);
		tabs.setForeground(Color.WHITE);
