	void displayResults(List<CofferItem> items, long scanTimestampMillis)
	{
		this.currentItems = items;
		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		if (scanTimestampMillis > 0L)
		{
			String formatted = TIMESTAMP_FMT.format(
				Instant.ofEpochMilli(scanTimestampMillis).atZone(ZoneId.systemDefault()));
			lastScanLabel.setText("Scanned " + formatted);
			lastScanLabel.setVisible(true);
		}
		else
		{
			lastScanLabel.setVisible(false);
		}
		renderResults();
		rebuildExclusionsTab();
	}

	void onConfigChanged()
	{
		renderResults();
		rebuildExclusionsTab();
	}

	void onFilterStateChanged()
	{
		if (showAllButton != null)
		{
			showAllButton.setVisible(plugin.isFilterActive());
		}
	}

	void showError(String message)
	{
		this.currentItems = Collections.emptyList();
		resultsContainer.removeAll();
		statusLabel.setText(message);
		statusLabel.setForeground(Color.RED);
		totalCofferLabel.setVisible(false);
		totalProfitLabel.setVisible(false);
		lastScanLabel.setVisible(false);
		resultsContainer.revalidate();
		resultsContainer.repaint();
	}

	private void renderResults()
	{
		resultsContainer.removeAll();

		NumberFormat fmt = NumberFormat.getNumberInstance(Locale.US);

		if (currentItems.isEmpty())
		{
			statusLabel.setText("No profitable items found.");
			totalCofferLabel.setVisible(false);
			totalProfitLabel.setVisible(false);
			JLabel none = new JLabel("No items qualify.");
			none.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			none.setFont(FontManager.getRunescapeSmallFont());
			none.setBorder(new EmptyBorder(8, 8, 0, 0));
			resultsContainer.add(none);
		}
		else
		{
			long totalCofferValue = 0L;
			long totalProfit = 0L;
			for (CofferItem item : currentItems)
			{
				totalCofferValue += (long) item.getCofferValue() * item.getQuantity();
				totalProfit += (long) item.getProfitOverHa() * item.getQuantity();
			}

			int n = currentItems.size();
			statusLabel.setText(n + " item" + (n == 1 ? "" : "s") + " found.");
			totalCofferLabel.setText("Total coffer value: " + fmt.format(totalCofferValue) + " gp");
			totalCofferLabel.setVisible(true);
			totalProfitLabel.setText("Profit vs High Alch: +" + fmt.format(totalProfit) + " gp");
			totalProfitLabel.setVisible(true);

			for (CofferItem item : currentItems)
			{
				resultsContainer.add(buildItemRow(item, fmt));
				resultsContainer.add(Box.createVerticalStrut(4));
			}
		}

		resultsContainer.revalidate();
		resultsContainer.repaint();
	}

	private JPanel buildItemRow(CofferItem item, NumberFormat fmt)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			new MatteBorder(1, 0, 0, 0, ColorScheme.DARK_GRAY_COLOR),
			new EmptyBorder(6, 8, 6, 8)
		));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel nameLbl = new JLabel(item.getName() + " ×" + fmt.format(item.getQuantity()));
		nameLbl.setFont(FontManager.getRunescapeBoldFont());
		nameLbl.setForeground(Color.WHITE);

		JButton excludeBtn = new JButton("Exclude");
		excludeBtn.setFocusPainted(false);
		excludeBtn.setFont(FontManager.getRunescapeSmallFont());
		excludeBtn.setForeground(Color.WHITE);
		excludeBtn.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
		excludeBtn.setOpaque(true);
		excludeBtn.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.BORDER_COLOR, 1),
			new EmptyBorder(0, 6, 0, 6)
		));
		excludeBtn.setMargin(new java.awt.Insets(0, 0, 0, 0));
		excludeBtn.setToolTipText("Stop flagging \"" + item.getName() + "\" in future scans");
		excludeBtn.addActionListener(e -> plugin.addExclusion(item.getItemId()));

		int headerHeight = Math.max(nameLbl.getPreferredSize().height, 16);
		Dimension btnSize = new Dimension(64, headerHeight);
		excludeBtn.setPreferredSize(btnSize);
		excludeBtn.setMinimumSize(btnSize);
		excludeBtn.setMaximumSize(btnSize);

		JPanel headerRow = new JPanel();
		headerRow.setLayout(new BoxLayout(headerRow, BoxLayout.X_AXIS));
		headerRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		headerRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		headerRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, headerHeight));
		headerRow.add(nameLbl);
		headerRow.add(Box.createHorizontalGlue());
		headerRow.add(excludeBtn);
		row.add(headerRow);

		boolean showGeHa = config.showGeHaPrices();
		boolean showCoffer = config.showCofferValue();
		boolean showPerItem = config.showProfitPerItem();
		boolean showStack = config.showStackProfit();

		if (showGeHa || showCoffer || showPerItem || showStack)
		{
			row.add(Box.createVerticalStrut(3));
		}

		if (showGeHa)
		{
			JLabel geLbl = new JLabel("GE: " + fmt.format(item.getGePrice()) + " gp  |  HA: " + fmt.format(item.getHaPrice()) + " gp");
			geLbl.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			geLbl.setFont(FontManager.getRunescapeSmallFont());
			geLbl.setAlignmentX(Component.LEFT_ALIGNMENT);
			row.add(geLbl);
		}

		if (showCoffer)
		{
			JLabel cofferLbl = new JLabel("Coffer: " + fmt.format(item.getCofferValue()) + " gp");
			cofferLbl.setForeground(PROFIT_GREEN);
			cofferLbl.setFont(FontManager.getRunescapeSmallFont());
			cofferLbl.setAlignmentX(Component.LEFT_ALIGNMENT);
			row.add(cofferLbl);
		}

		if (showPerItem)
		{
			JLabel perItemLbl = new JLabel("+" + fmt.format(item.getProfitOverHa()) + " gp/item vs HA");
			perItemLbl.setForeground(PROFIT_GREEN);
			perItemLbl.setFont(FontManager.getRunescapeSmallFont());
			perItemLbl.setAlignmentX(Component.LEFT_ALIGNMENT);
			row.add(perItemLbl);
		}

		if (showStack)
		{
			long stackProfit = (long) item.getProfitOverHa() * item.getQuantity();
			JLabel stackLbl = new JLabel("Stack profit: +" + fmt.format(stackProfit) + " gp");
			stackLbl.setForeground(PROFIT_GREEN);
			stackLbl.setFont(FontManager.getRunescapeSmallFont());
			stackLbl.setAlignmentX(Component.LEFT_ALIGNMENT);
			row.add(stackLbl);
		}

		Dimension pref = row.getPreferredSize();
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, pref.height));
		return row;
	}

	private void rebuildExclusionsTab()
	{
		if (exclusionsContainer == null || exclusionsHeaderLabel == null)
		{
			return;
		}
		exclusionsContainer.removeAll();

		Map<Integer, String> excluded = plugin.getExcludedItems();
		int n = excluded.size();
		exclusionsHeaderLabel.setText(n == 0
			? "No items excluded"
			: n + " item" + (n == 1 ? "" : "s") + " excluded");

		if (n == 0)
		{
			JLabel empty = new JLabel(
				"<html><body style='width:185px'>"
					+ "Use the \"Exclude\" button on a scan result to add items here."
					+ "</body></html>"
			);
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setBorder(new EmptyBorder(8, 8, 0, 8));
			empty.setAlignmentX(Component.LEFT_ALIGNMENT);
			exclusionsContainer.add(empty);
		}
		else
		{
			for (Map.Entry<Integer, String> entry : excluded.entrySet())
			{
				exclusionsContainer.add(buildExclusionRow(entry.getKey(), entry.getValue()));
				exclusionsContainer.add(Box.createVerticalStrut(2));
			}
		}

		exclusionsContainer.revalidate();
		exclusionsContainer.repaint();
	}

	private JPanel buildExclusionRow(int id, String name)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			new MatteBorder(1, 0, 0, 0, ColorScheme.DARK_GRAY_COLOR),
			new EmptyBorder(6, 8, 6, 8)
		));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel nameLbl = new JLabel(name);
		nameLbl.setForeground(Color.WHITE);
		nameLbl.setFont(FontManager.getRunescapeFont());
		nameLbl.setToolTipText("Item ID: " + id);

		JButton includeBtn = new JButton("Include");
		includeBtn.setFocusPainted(false);
		includeBtn.setFont(FontManager.getRunescapeSmallFont());
		includeBtn.setForeground(Color.WHITE);
		includeBtn.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
		includeBtn.setOpaque(true);
		includeBtn.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.BORDER_COLOR, 1),
			new EmptyBorder(0, 6, 0, 6)
		));
		includeBtn.setMargin(new java.awt.Insets(0, 0, 0, 0));
		includeBtn.setToolTipText("Remove \"" + name + "\" from the exclusion list");
		includeBtn.addActionListener(e -> plugin.removeExclusion(id));

		int rowHeight = Math.max(nameLbl.getPreferredSize().height, 16);
		Dimension btnSize = new Dimension(64, rowHeight);
		includeBtn.setPreferredSize(btnSize);
		includeBtn.setMinimumSize(btnSize);
		includeBtn.setMaximumSize(btnSize);

		row.add(nameLbl);
		row.add(Box.createHorizontalGlue());
		row.add(includeBtn);

		Dimension pref = row.getPreferredSize();
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, pref.height));
		return row;
	}
}

